content.solution_code:
class Spacecraft {
  constructor(name, fuel) {
    this.name = name;
    this.fuel = fuel;
  }

  launch() {
    return `${this.name} is launching with ${this.fuel} units of fuel!`;
  }
}

class ExplorerShip extends Spacecraft {
  constructor(name, fuel, scannerType) {
    super(name, fuel);
    this.scannerType = scannerType;
  }

  scanPlanets() {
    return `${this.name} is scanning planets with its ${this.scannerType} scanner!`;
  }
}

